import{az as i,P as l,Q as a,aQ as r}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const S=JSON.parse('{"title":"项目：Lego 可视化页面搭建平台","description":"","frontmatter":{},"headers":[],"relativePath":"其他/resume.md","filePath":"其他/resume.md","lastUpdated":1781716938000}'),o={name:"其他/resume.md"};function t(n,e,s,d,c,h){return l(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="项目-lego-可视化页面搭建平台" tabindex="-1">项目：Lego 可视化页面搭建平台 <a class="header-anchor" href="#项目-lego-可视化页面搭建平台" aria-label="Permalink to “项目：Lego 可视化页面搭建平台”">​</a></h1><h2 id="项目概述" tabindex="-1">项目概述 <a class="header-anchor" href="#项目概述" aria-label="Permalink to “项目概述”">​</a></h2><p>Lego 是一个我个人独立设计与开发的低代码可视化页面搭建平台。项目基于 Vue 3 + Vite 构建，目标是让用户像搭乐高积木一样，通过拖拽组件、可视化配置和导出功能快速生成 H5 页面。</p><h2 id="我的角色" tabindex="-1">我的角色 <a class="header-anchor" href="#我的角色" aria-label="Permalink to “我的角色”">​</a></h2><ul><li>个人项目负责人：独立完成产品设计、前端架构、功能开发与优化</li><li>技术栈与实现：Vue 3、Vite、Pinia、Element Plus、Tailwind CSS、SCSS、Vue Router</li><li>核心功能开发：拖拽画布、组件属性编辑、样式面板、页面导出、编译/反编译引擎</li></ul><h2 id="核心功能亮点" tabindex="-1">核心功能亮点 <a class="header-anchor" href="#核心功能亮点" aria-label="Permalink to “核心功能亮点”">​</a></h2><ul><li><strong>可视化搭建体验</strong>：实现拖拽排序与缩放，支持在画布上自由编辑组件位置和结构</li><li><strong>组件库与属性面板</strong>：构建组件面板与属性控制面板，可编辑文本、图片、按钮、链接、输入框、轮播图等元素</li><li><strong>样式与交互配置</strong>：支持可视化 CSS 样式配置、动画设置、事件与交互面板</li><li><strong>编译/反编译系统</strong>：设计并实现 <code>compile</code> 与 <code>decompile</code> 模块，将内部 VNode Schema 转换为 HTML，并支持从 HTML/CSS 恢复页面结构</li><li><strong>页面导出能力</strong>：支持导出可部署的 HTML 页面，便于线上发布与交付</li><li><strong>微前端兼容</strong>：支持通过 <code>dev:micro</code> / <code>build:micro</code> 模式接收父应用传入 Schema，作为微前端子应用运行</li></ul><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to “技术栈”">​</a></h2><ul><li>框架：Vue 3（Composition API + JSX）</li><li>构建工具：Vite 8</li><li>状态管理：Pinia（含持久化插件）</li><li>UI 组件库：Element Plus</li><li>CSS：SCSS + Tailwind CSS 4</li><li>路由：Vue Router 5</li><li>拖拽：SortableJS</li><li>轮播：Swiper 8</li><li>代码编辑器与高亮：Ace Editor + Highlight.js</li><li>HTTP 请求：Axios</li></ul><h2 id="项目成果" tabindex="-1">项目成果 <a class="header-anchor" href="#项目成果" aria-label="Permalink to “项目成果”">​</a></h2><ul><li>搭建了一个完整的可视化 H5 页面编辑器，覆盖页面构建、样式配置、交互管理与导出流程</li><li>实现了从编辑态到导出结果的端到端编译能力，提升项目可落地交付性</li><li>该项目适用于运营活动页、落地页等快速搭建场景，体现了我的产品思考与前端实现能力</li></ul><h2 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to “个人收获”">​</a></h2><ul><li>深入掌握 Vue 3 组合式 API 与 Vite 开发流程</li><li>熟悉复杂组件交互、画布渲染、可视化编辑器架构设计</li><li>实践了独立完成大型前端项目从需求到实现的能力</li></ul>',13)])])}const g=i(o,[["render",t]]);export{S as __pageData,g as default};
